package com.emssystem.emsleaveservice.pto.repository; import com.emssystem.emsleaveservice.pto.entity.PtoRequest; import com.emssystem.emsleaveservice.pto.enums.PtoRequestStatus; import org.springframework.data.jpa.repository.JpaRepository; import java.time.LocalDate; import java.util.List;
